def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit that transforms s_in to s_out."""
    # Find first position where they differ
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            # Check if we're inserting or deleting
            if len(s_in) > len(s_out):
                # Delete at position i
                return (s_in[i], "", i)
            elif len(s_in) < len(s_out):
                # Insert at position i
                return ("", s_out[i], i)
            else:
                # Replace at position i
                return (s_in[i], s_out[i], i)

    # If we reach here, one string is prefix of other
    if len(s_in) > len(s_out):
        return (s_in[-1], "", len(s_out))
    elif len(s_in) < len(s_out):
        return ("", s_out[-1], len(s_in))
    else:
        return ("", "", -1)  # No difference

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a change."""
    # Get minimal edit
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # If it's a simple character replacement
    if old_sub and new_sub and pos >= 0:
        return [(old_sub, new_sub)]
    # If it's insertion or deletion, let's look for patterns
    elif old_sub and not new_sub:
        # Deletion case
        return [(old_sub, "")]
    elif not old_sub and new_sub:
        # Insertion case
        return [(new_sub, new_sub)]  # This won't work well, so we'll return nothing meaningful
    else:
        # Full replacement case
        return [(s_in, s_out)]

